import { expect, expectStatus, test, type APIRequestContext } from "../../fixtures";

const SAMPLE_BYTES = Buffer.from("%PDF-1.4 vendor intake sample\n", "utf-8");
const KINDS = ["w9", "insurance_certificate", "contract"] as const;

function uniqueVendorName(): string {
  return `REV-05 Vendor ${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

async function waitForExtraction(member: APIRequestContext, documentId: string): Promise<string> {
  let extractionId = "";
  await expect
    .poll(
      async () => {
        const doc = await expectStatus<{ status: string }>(await member.get(`/api/documents/${documentId}`), 200);
        if (doc.status === "extracted") {
          const extraction = await expectStatus<{ id: string; status: string }>(
            await member.get(`/api/documents/${documentId}/extraction`),
            200,
          );
          extractionId = extraction.id;
        }
        return doc.status;
      },
      { timeout: 60_000, intervals: [500, 1000, 2000] },
    )
    .toBe("extracted");
  return extractionId;
}

test.describe("review vendors", () => {
  test("approving every extraction approves the vendor", { tag: "@REV-05" }, async ({ apiAs }) => {
    // Arrange: a member creates a vendor and uploads all three documents.
    const member = await apiAs("member");
    const reviewer = await apiAs("reviewer");

    const vendor = await expectStatus<{ id: string; status: string }>(
      await member.post("/api/vendors", {
        data: {
          name: uniqueVendorName(),
          category: "software",
          contact_email: `rev05-${Date.now()}-${Math.random().toString(36).slice(2, 8)}@vendor.test`,
        },
      }),
      201,
    );
    expect(vendor.status).toBe("draft");

    const documentIds: string[] = [];
    for (const kind of KINDS) {
      const doc = await expectStatus<{ id: string }>(
        await member.post(`/api/vendors/${vendor.id}/documents`, {
          multipart: {
            kind,
            file: { name: `${kind}.pdf`, mimeType: "application/pdf", buffer: SAMPLE_BYTES },
          },
        }),
        201,
      );
      documentIds.push(doc.id);
    }

    // Wait for all three documents to be extracted, then collect their extraction ids.
    const extractionIds: string[] = [];
    for (const documentId of documentIds) {
      extractionIds.push(await waitForExtraction(member, documentId));
    }
    expect(extractionIds).toHaveLength(3);

    // Member submits the vendor for review.
    const submitted = await expectStatus<{ status: string }>(
      await member.post(`/api/vendors/${vendor.id}/submit`),
      200,
    );
    expect(submitted.status).toBe("in_review");

    // Act: reviewer approves all three extractions.
    for (const extractionId of extractionIds) {
      const decided = await expectStatus<{ status: string }>(
        await reviewer.post(`/api/extractions/${extractionId}/decision`, {
          data: { decision: "approve" },
        }),
        200,
      );
      expect(decided.status).toBe("approved");
    }

    // Assert: vendor status is approved.
    const finalVendor = await expectStatus<{ status: string }>(
      await reviewer.get(`/api/vendors/${vendor.id}`),
      200,
    );
    expect(finalVendor.status).toBe("approved");

    // Assert: an audit event "vendor.approved" is recorded.
    const trail = await expectStatus<{ items: { action: string }[] }>(
      await reviewer.get(`/api/vendors/${vendor.id}/audit`),
      200,
    );
    expect(trail.items.map((event) => event.action)).toContain("vendor.approved");
  });
});
